"use strict";

/**
 * Blue canvas for Peanut the bunny.
 * 
*/
function setup() {
// Once at the beginning of the program
    createCanvas(500, 500);
}


/**
 * This function draws the scene for Peanut the bunny.
 */
function draw() {
    //Every Frame 
    background("#B5DAFE");

    // Head
    fill("#3C280D");
    noStroke();
    ellipse(250, 280, 270, 230);

    
}
